const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.table}"/></svg>`;
const btn=(action,label,ico,cls='small-btn')=>`<button class="${cls}" data-action="${action}" title="${esc(label)}" aria-label="${esc(label)}">${ico?icon(ico):''}<span>${label}</span></button>`;
const ib=(action,label,ico)=>`<button class="icon-btn" data-action="${action}" title="${label}" aria-label="${label}">${icon(ico)}</button>`;
