let initialized=false,busy=false,pendingImportToken;
const tasks=createWorkbookTasks({onSave:state=>{const el=$('#save-state');if(el)el.textContent=state==='saved'?'이 기기에 저장됨':state==='saving'?'자동 복구 저장 중…':'자동 복구 저장 실패 · 파일로 저장하세요';},onCalculated:()=>{if(initialized)render();},onError:error=>toast(error.message)});
