const recovered=await tasks.load(localStorage.getItem('sheet-studio.book')||'');
if(recovered.migrated)localStorage.removeItem('sheet-studio.book');
const history=createHistory(recovered.book,{description:recovered.description});
const documentLocation=createDocumentLocation(()=>history.raw,localStorage);
let book=history.book;
function formatValue(value,style){return formatWorkbookValue(value,style,book);}
function bindEvaluator(){setExternalEvaluator(history.raw,(id,ref)=>tasks.value(id,ref));}
bindEvaluator();
async function runBusy(label,operation){if(busy)return;busy=true;const overlay=document.createElement('div');overlay.className='workbook-busy';overlay.setAttribute('role','status');overlay.innerHTML='<span class="workbook-spinner"></span><span></span>';overlay.lastChild.textContent=label;document.body.append(overlay);try{return await operation();}catch(error){history.rollback();book=history.book;bindEvaluator();if(initialized){makeLayout();syncToolbar();render();renderSheets();updateTitle();}toast(error.message);}finally{busy=false;overlay.remove();}}

let selection={r:0,c:0,r2:0,c2:0},tab='홈',editing=false,dragging=false,fillStart=null,clipboard=null,dirty=false,zoom=100,showGrid=true,showFormulas=false,searchText='',filteredRows=null,filterEnabled=false,layout,frame=0,menu=null,menuScrollOffsets=new WeakMap(),toastTimer;
let editSession=null,editInput=null,referenceDrag=null,keyboardReference=null,pointMode=false;
const MAX_ROWS=1048576,MAX_COLS=16384,HEADER_W=40,HEADER_H=25;
const sheet=()=>book.sheets.find(s=>s.id===book.activeSheetId)||book.sheets[0];
const rawAt=(r,c)=>sheet().cells[address(r,c)]?.raw||'';
const valueAt=(r,c)=>evaluateCell(book,sheet().id,address(r,c));
const bounds=()=>({r1:Math.min(selection.r,selection.r2),r2:Math.max(selection.r,selection.r2),c1:Math.min(selection.c,selection.c2),c2:Math.max(selection.c,selection.c2)});
const hiddenRow=r=>filteredRows?.has(r)||sheet().rowHeights?.[r]===0;
const hiddenCol=c=>sheet().columnWidths?.[c]===0;
function editableCell(r,c){return !hiddenRow(r)&&!hiddenCol(c)&&!mergeRanges().some(m=>r>=m.r1&&r<=m.r2&&c>=m.c1&&c<=m.c2&&(r!==m.r1||c!==m.c1));}
function forSelection(fn){const b=bounds();if((b.r2-b.r1+1)*(b.c2-b.c1+1)>100000){toast('한 번에 최대 100,000개 셀을 편집할 수 있습니다.');return false;}for(let r=b.r1;r<=b.r2;r++)for(let c=b.c1;c<=b.c2;c++)if(editableCell(r,c))fn(address(r,c),r,c);return true;}
function permitOperation(operation){if(protectionAllows(sheet(),operation))return true;toast('보호된 시트에서 이 작업은 허용되지 않습니다.');return false;}
function permitUpdates(updates,options={}){try{assertCellUpdates(book,sheet(),updates,options);return true;}catch(error){toast(error.message);return false;}}
function preserveProtectedFormatting(updates){if(!sheetIsProtected(sheet()))return;for(const update of updates){const old=sheet().cells[update.key];update.cell.xlsxProtection=cloneData(cellProtection(book,sheet(),update.key));if(!protectionAllows(sheet(),'formatCells')){update.cell.style=cloneData(old?.style||{});if(old?.xlsxStyle!==undefined)update.cell.xlsxStyle=old.xlsxStyle;else delete update.cell.xlsxStyle;if(update.cell.xlsxValue?.value?.richText)delete update.cell.xlsxValue;}}}

function checkpoint(){history.begin();}
function changed({rebuild=false}={}){try{const result=history.commit();if(result.discarded)toast('큰 변경으로 실행 취소의 메모리 한도를 넘어 이전 기록을 비웠습니다.',true);}catch(error){book=history.book;bindEvaluator();makeLayout();syncToolbar();render();renderSheets();updateTitle();toast(error.message);return false;}dirty=true;documentLocation.id();const updates=history.takeDirty();refreshConstraintIndexes(history.raw,updates);refreshClipboard(updates);renderPivotBar();tasks.sync(history.raw,updates,pendingImportToken);pendingImportToken=undefined;if(rebuild)makeLayout();syncToolbar();render();renderSheets();updateTitle();return true;}
function toast(message,historyLimit=false){const previous=$('.toast');if(previous?.dataset.historyLimit==='true'&&!historyLimit)message+=' '+previous.textContent;previous?.remove();const el=document.createElement('div');el.className='toast';el.dataset.historyLimit=String(historyLimit);el.textContent=message;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3200);}
function rangeLabel(){const b=bounds();return b.r1===b.r2&&b.c1===b.c2?address(b.r1,b.c1):`${address(b.r1,b.c1)}:${address(b.r2,b.c2)}`;}
