 if(tab==='삽입')html=group('표',btn('pivot','피벗테이블','table','large-btn')+btn('table-style','표 서식','table','large-btn'))+group('차트',btn('chart-bar','세로 막대형','chart','large-btn')+btn('chart-line','꺾은선형','chart','large-btn')+btn('chart-insert','모든 차트','chart','large-btn'))+group('워크시트',btn('add-sheet','새 시트','plus','large-btn')+btn('duplicate-sheet','시트 복제','copy','large-btn'));
