async function chartSelectionRange(){const b=bounds();if(b.r1!==b.r2||b.c1!==b.c2)return b;return runBusy('차트 데이터 영역을 확인하는 중…',async()=>await tasks.run('infer-region',{sheetId:sheet().id,selection:b})||b);}
async function editChart(id){if(commitEdit()===false||!permitOperation('objects'))return;const target=id?sheet().charts.find(c=>c.id===id):null;let range=rangeLabel();if(!target){const b=await chartSelectionRange();if(!b)return;range=boundsLabel(b);}chartDialog({chart:target,range,sheet:sheet(),workbook:book,modal,onApply:patch=>{checkpoint();if(target)Object.assign(target,patch);else sheet().charts.push({id:crypto.randomUUID(),x:($('#grid').scrollLeft+280)/(zoom/100),y:($('#grid').scrollTop+35)/(zoom/100),width:600,height:360,...patch});changed();}});}
