function setZoom(n){zoom=Math.max(50,Math.min(180,n));$('#zoom').value=zoom;$('#zoom-label').textContent=zoom+'%';makeLayout();render();}
function printSheet(){const u=usedBounds();if((u.r+1)*(u.c+1)>20000)return toast('인쇄할 데이터가 너무 큽니다. 범위를 줄여 주세요.');const frame=document.createElement('iframe');frame.style.cssText='position:fixed;width:0;height:0;border:0';document.body.append(frame);const evaluate=createEvaluator(book,sheet().id),conditionalStyle=createConditionalEvaluator(book,sheet(),evaluate);const rows=[];for(let r=0;r<=u.r;r++){if(filteredRows?.has(r)||sheet().rowHeights?.[r]===0)continue;let row='';for(let c=0;c<=u.c;c++){if(sheet().columnWidths[c]===0)continue;const cell=sheet().cells[address(r,c)]||{},s={...cell.style,...conditionalStyle(r,c,evaluate(address(r,c)))};row+=`<td style="background:${esc(s.background||'white')};color:${esc(s.color||'#222')};font-weight:${s.bold?'bold':'normal'};text-align:${s.align||'left'};vertical-align:${s.verticalAlign||'middle'};${bordersCss(s)}">${esc(formatValue(valueAt(r,c),s))}</td>`;}rows.push(`<tr>${row}</tr>`);}frame.contentDocument.write(`<html><head><title>${esc(book.name)}</title><style>@page{size:A4 ${document.querySelector('#print-direction')?.textContent.includes('landscape')?'landscape':'portrait'};margin:12mm}body{font:10px Arial}h1{font-size:17px}table{border-collapse:collapse;width:100%}td{border:1px solid #ccc;padding:5px}</style></head><body><h1>${esc(book.name)} · ${esc(sheet().name)}</h1><table>${rows.join('')}</table></body></html>`);frame.contentDocument.close();frame.contentWindow.focus();frame.contentWindow.print();setTimeout(()=>frame.remove(),10000);}

document.addEventListener('click',e=>{const arrow=e.target.closest('[data-filter-column]');if(arrow){openColumnFilter(+arrow.dataset.filterColumn,arrow.getBoundingClientRect());return;}const button=e.target.closest('[data-action]');if(button){action(button.dataset.action,e);return;}if(!e.target.closest('.menu'))closeMenu();const t=e.target.closest('[data-tab]');if(t){if(commitEdit()===false)return;if(t.dataset.tab==='파일'){showMenu(t.getBoundingClientRect().left,t.getBoundingClientRect().bottom,[['new','새 통합 문서','file','Ctrl+N'],['open','열기','open','Ctrl+O'],['save',book.nativeSource?'XLSM 저장 (VBA 유지)':'XLSX 저장','save','Ctrl+S'],['vba','Excel에서 VBA 실행','formula'],['save-csv','CSV 저장','download'],['save-json','앱 문서 저장 (.sheet.json)','download'],'-',['demo','예제 통합 문서','table'],['print','인쇄 / PDF','file']]);return;}tab=t.dataset.tab;document.querySelectorAll('[data-tab]').forEach(el=>el.classList.toggle('active',el.dataset.tab===tab));$('#ribbon').classList.remove('collapsed');renderRibbon();render();}const s=e.target.closest('[data-sheet]');if(s&&!showReferenceSheet(s.dataset.sheet))switchSheet(s.dataset.sheet);const config=e.target.closest('[data-edit-chart]');if(config)editChart(config.dataset.editChart);const del=e.target.closest('[data-remove-chart]');if(del){if(!permitOperation('objects'))return;checkpoint();sheet().charts=sheet().charts.filter(c=>c.id!==del.dataset.removeChart);changed();}});
document.addEventListener('mousedown',e=>{const cell=e.target.closest('.cell');if(e.button!==0||!cell||e.target.closest('[data-filter-column]'))return;e.preventDefault();if(e.detail===2&&!e.shiftKey&&!e.ctrlKey&&!e.metaKey&&!editing)editCellAtPointer(e,cell);});
