$('#name-box').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();try{const [a,b]=e.target.value.toUpperCase().replace(/\$/g,'').split(':').map(parseAddress);if(!a||e.target.value.split(':').length>2||e.target.value.includes(':')&&!b)throw Error();if(commitEdit()===false)return;select(a.r,a.c,false,true);if(b){selection.r2=b.r;selection.c2=b.c;render();}focusGrid();}catch{toast('올바른 주소를 입력하세요. 예: A1 또는 A1:C10');}}});
$('#book-title').addEventListener('change',e=>{const name=e.target.value.trim()||'통합 문서';if(commitEdit()===false)return;checkpoint();book.name=name;changed();});$('#zoom').addEventListener('input',e=>setZoom(+e.target.value));
