document.addEventListener('paste',e=>{if(busy){e.preventDefault();return;}if(!gridInputFocused())return;e.preventDefault();try{pasteContent(e.clipboardData.getData('text/plain'),e.clipboardData.getData('text/html'));}catch(err){toast(err.message);}});
